import sys
from pathlib import Path

ARQUIVO = Path("tarefas.txt")


def carregar():
    if not ARQUIVO.exists():
        return []
    return ARQUIVO.read_text(encoding="utf-8").splitlines()


def salvar(tarefas):
    conteudo = "".join(tarefa + "\n" for tarefa in tarefas)
    ARQUIVO.write_text(conteudo, encoding="utf-8")


def adicionar(texto):
    tarefas = carregar()
    tarefas.append(texto)
    salvar(tarefas)
    print(f"Tarefa {len(tarefas)} adicionada: {texto}")


def listar():
    tarefas = carregar()
    if not tarefas:
        print("Nenhuma tarefa.")
        return
    for numero, tarefa in enumerate(tarefas, start=1):
        print(f"{numero}. {tarefa}")


def concluir(numero):
    tarefas = carregar()
    if not 1 <= numero <= len(tarefas):
        print(f"Não existe a tarefa {numero}.")
        return
    feita = tarefas.pop(numero - 1)
    salvar(tarefas)
    print(f"Concluída: {feita}")


def ajuda():
    print("Uso:")
    print('  python3 tarefas.py adicionar "texto da tarefa"')
    print("  python3 tarefas.py listar")
    print("  python3 tarefas.py concluir NÚMERO")


if len(sys.argv) < 2:
    ajuda()
    sys.exit(1)

comando = sys.argv[1]

if comando == "adicionar" and len(sys.argv) >= 3:
    adicionar(" ".join(sys.argv[2:]))
elif comando == "listar":
    listar()
elif comando == "concluir" and len(sys.argv) == 3 and sys.argv[2].isdigit():
    concluir(int(sys.argv[2]))
else:
    ajuda()
    sys.exit(1)

