import sys

numeros = []
for texto in sys.argv[1:]:
    try:
        numeros.append(float(texto))
    except ValueError:
        print(f"Ignorado: '{texto}' não é número")

if numeros:
    print(f"Maior: {max(numeros)}")
    print(f"Menor: {min(numeros)}")
else:
    print("Nenhum número válido.")
    sys.exit(1)

def limpar():
    tarefas = carregar()
    if not tarefas:
        print("Nenhuma tarefa para apagar.")
        return
    resposta = input(f"Apagar {len(tarefas)} tarefa(s)? (s/n) ").strip().lower()
    if resposta == "s":
        salvar([])
        print("Lista apagada.")
    else:
        print("Nada foi apagado.")
